			Target:           SkillCollapseTargetUserMessage,
			Label:            command,
			DefaultCollapsed: true,
		},
	}
	if !timestamp.IsZero() {
		event.Timestamp = timestamp.UTC().Format(time.RFC3339Nano)
	}
	return event, true
}

