func skillEventLabels(events []agent.SkillEvent) []string {
	seen := make(map[string]struct{}, len(events))
	labels := make([]string, 0, len(events))
	for _, event := range events {
		label := event.Collapse.Label
		if label == "" && event.Native != nil {
			label = event.Native["command"]
		}
		if label == "" {
			label = event.Skill.Name
		}
		if label == "" {
			continue
		}
		if _, ok := seen[label]; ok {
			continue
		}
		seen[label] = struct{}{}
		labels = append(labels, label)
	}
	return labels
}

func writeSessionTokensJSON(w io.Writer, report sessionTokensReport) error {
	enc := json.NewEncoder(w)
	enc.SetIndent("", "  ")
	if err := enc.Encode(report); err != nil {
		return fmt.Errorf("failed to encode session token report: %w", err)
	}
	return nil
}

func writeSessionTokensText(w io.Writer, report sessionTokensReport) error {
	fmt.Fprintln(w, "Session tokens")
	fmt.Fprintln(w)
	fmt.Fprintf(w, "Session: %s\n", report.SessionID)
	fmt.Fprintf(w, "Agent:   %s\n", report.Agent)
	if report.Model != "" {
		fmt.Fprintf(w, "Model:   %s\n", report.Model)
	}
	fmt.Fprintf(w, "Status:  %s\n", report.Status)

	if report.Tokens != nil {
		fmt.Fprintln(w)
		fmt.Fprintf(w, "Total:  %s tokens\n", formatTokenCount(report.Tokens.Total))
		parts := []string{
			"Input: " + formatTokenCount(report.Tokens.Input),
			"Cache read: " + formatTokenCount(report.Tokens.CacheRead),
			"Cache write: " + formatTokenCount(report.Tokens.CacheWrite),
			"Output: " + formatTokenCount(report.Tokens.Output),
			fmt.Sprintf("API calls: %d", report.Tokens.APICalls),
		}
		fmt.Fprintf(w, "  %s\n", strings.Join(parts, " | "))
	} else {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Token data: unavailable")
	}

	if len(report.Contributors) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Likely contributors")
		for _, contributor := range report.Contributors {
			switch contributor.Kind {
			case "subagents":
				fmt.Fprintf(w, "- %s: %s tokens\n", contributor.Label, formatTokenCount(contributor.Tokens))
			case "context_pressure":
				if report.Context != nil {
					fmt.Fprintf(w, "- %s: %d%% of %s tokens\n", contributor.Label, report.Context.Percent, formatTokenCount(report.Context.WindowSize))
				}
			default:
				fmt.Fprintf(w, "- %s\n", contributor.Label)
			}
		}
	}

	if len(report.Recommendations) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Recommendations")
		for _, rec := range report.Recommendations {
			fmt.Fprintf(w, "- %s\n", rec.Message)
		}
	}

	if len(report.Limitations) > 0 {
		fmt.Fprintln(w)
		fmt.Fprintln(w, "Limitations")
		for _, limitation := range report.Limitations {
			fmt.Fprintf(w, "- %s\n", limitation)
		}
	}

	return nil
}

